<script setup lang="ts">import {computed,ref} from 'vue';import {Search,ArrowUpRight} from 'lucide-vue-next';import SectionHeading from '../components/SectionHeading.vue';import {resources} from '../data/site';const q=ref('');const filtered=computed(()=>resources.filter(r=>(r.title+r.desc+r.type).toLowerCase().includes(q.value.toLowerCase())))</script><template><div class="inner-page"><div class="page-hero"><div class="eyebrow">BOOKMARKS / KNOWLEDGE BASE</div><h1>资源<span class="gradient-text">导航。</span></h1><p>收藏值得反复访问的开发工具、AI 平台与创意资源。</p></div><div class="resource-search"><Search :size="18"/><input v-model="q" placeholder="搜索工具、平台或关键词..." aria-label="搜索资源"/></div><SectionHeading eyebrow="CURATED LINKS" :title="'资源列表 · '+filtered.length" desc="点击卡片访问官方网站。"/><div class="resource-grid"><a v-for="r in filtered" :key="r.title" :href="r.url" target="_blank" rel="noreferrer" class="resource-item"><span class="resource-type">{{r.type}}</span><strong>{{r.title}}</strong><p>{{r.desc}}</p><ArrowUpRight :size="16" class="resource-arrow"/></a></div><p v-if="!filtered.length" class="empty-state">没有找到匹配的资源，试试其他关键词。</p></div></template>